def word_wrap(text, width):
    words = text.split()
    lines = []
    current_line = ""

    for word in words:
        if len(word) > width:
            if current_line:
                lines.append(current_line.strip())
                current_line = ""
            lines.append(word)
        elif len(current_line) + len(word) + 1 > width:
            lines.append(current_line.strip())
            current_line = word
        else:
            current_line += " " + word if current_line else word

    if current_line:
        lines.append(current_line.strip())

    return lines
```

