def edit_distance(a, b):
    if not a and not b:
        return 0
    if not a:
        return len(b)
    if not b:
        return len(a)
    return min(
        edit_distance(a[:-1], b[:-1]) + 1,  # Deletion
        edit_distance(a[:-1], b[:-1])      # Insertion
    ) + (a[-1] != b[-1])                   # Substitution
```

