def two_sum(nums, target):
    """
    Given an array of integers nums and an integer target, return [i, j] with i < j and nums[i] + nums[j] == target;
    if several pairs work, return the one with the smallest i, and for that i the smallest j;
    return None if no pair exists.
    """
    num_map = {}
    for i, num in enumerate(nums):
        complement = target - num
        if complement in num_map:
            j = num_map[complement]
            if i < j:
                return [i, j]
            else:
                return [j, i]
        num_map[num] = i
    return None
