def pascal_row(n):
    """Returns row n (0-indexed) of Pascal's triangle as a list of integers.
    pascal_row(0) is [1]. Edge cases matter, so please handle them.
    """
    if n == 0:
        return [1]
    elif n == 1:
        return [1, 1]
    else:
        row = [1]
        for i in range(1, n + 1):
            new_row = [1]
            for j in range(len(row) - 1):
                new_row.append(row[j] + row[j+1])
            new_row.append(1)
            row = new_row
        return row
```

