def word_wrap(text, width):
    """Greedily wraps the words of text into lines of at most width characters.

    Args:
        text: The input string to wrap.
        width: The maximum width of each line.

    Returns:
        A list of strings, where each string is a line of wrapped text.
    """
    if not text:
        return []

    words = text.split()
    lines = []
    current_line = ""

    for word in words:
        if len(word) > width:
            if current_line:
                lines.append(current_line)
            lines.append(word)
            current_line = ""
        elif len(current_line) == 0:
            if len(word) <= width:
                current_line = word
            else:
                lines.append(word)
                current_line = ""
        elif len(current_line) + len(word) + 1 <= width:
            current_line += " " + word
        else:
            lines.append(current_line)
            current_line = word

    if current_line:
        lines.append(current_line)

    return lines
```

