        if n < 70:
            return "sixty" + " " + less_than_20[n - 60]

        if n < 80:
            return "seventy" + " " + less_than_20[n - 70]

        if n < 90:
            return "eighty" + " " + less_than_20[n - 80]

        if n < 100:
            return "ninety" + " " + less_than_20[n - 90]

        tens = ["", "ten", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"]
        ones = less_than_20

        if n % 10 == 0:
            return tens[n // 10]
        else:
            return tens[n // 10] + "-" + ones[n % 10]

    if n == 0:
        return "zero"

    if n >= 100 and n < 1000:
        hundreds = less_than_20[n // 100]
        remaining = n % 100
        if remaining == 0:
            return hundreds + " hundred"
        else:
            return hundreds + " hundred " + _number_to_words(remaining)

    return _number_to_words(n)
```

```python
def edit_distance(a, b):
    """
    Calculates the Levenshtein edit distance between two strings.

    Args:
        a: The first string.
        b: The second string.

    Returns:
        The Levenshtein edit distance between a and b.
    """
    if a is None or b is None:
        return max(len(a) if a is not None else 0, len(b) if b is not None else 0)

    n = len(a)
    m = len(b)

    dp = [[0] * (m + 1) for _ in range(n + 1)]

    for i in range(n + 1):
        dp[i][0] = i
    for j in range(m + 1):
        dp[0][j] = j

    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if a[i - 1] == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = 1 + min(dp[i - 1][j],      # Deletion
                                   dp[i][j - 1],      # Insertion
                                   dp[i - 1][j - 1])  # Substitution

    return dp[n][m]
```

