def min_coins(coins, amount):
    """
    Given a list of coin denominations and an amount, return the minimum number of coins
    from the list coins (unlimited supply of each denomination) needed to make exactly amount,
    or -1 if it is impossible; amount 0 needs 0 coins.
    For example:
    min_coins([1, 2, 5], 11) == 3
    min_coins([2], 3) == -1
    min_coins([1], 0) == 0
    """
    dp = [float('inf')] * (amount + 1)
    dp[0] = 0
    for i in range(1, amount + 1):
        for coin in coins:
            if i - coin >= 0:
                dp[i] = min(dp[i], dp[i - coin] + 1)
    if dp[amount] == float('inf'):
        return -1
    else:
        return dp[amount]
```

