    result = []
    b_counts = {}
    for x in b:
        b_counts[x] = b_counts.get(x, 0) + 1
    for x in a:
        if x not in b_counts or b_counts[x] == 0:
            result.append(x)
        else:
            b_counts[x] -= 1
    return result
