def word_wrap(text, width):
    words = text.split()
    lines = []
    current_line = []

    for word in words:
        # Check if adding the next word would exceed the width
        if len(' '.join(current_line + [word])) <= width:
            current_line.append(word)
        else:
            # If the word itself is longer than the width, start a new line
            if len(word) > width:
                lines.append(word)
                current_line = []
            else:
                # Otherwise, finalize the current line and start a new one
                if current_line:
                    lines.append(' '.join(current_line))
                    current_line = [word]
                else:
                    current_line = [word]

    # Add the last line if there are any words left
    if current_line:
        lines.append(' '.join(current_line))

    return lines
