def edit_distance(a: str, b: str) -> int:
    len_a, len_b = len(a), len(b)
    if len_a == 0:
        return len_b
    if len_b == 0:
        return len_a

    dp = [[0] * (len_b + 1) for _ in range(len_a + 1)]

    for i in range(len_a + 1):
        dp[i][0] = i
    for j in range(len_b + 1):
        dp[0][j] = j

    for i in range(1, len_a + 1):
        for j in range(1, len_b + 1):
            if a[i - 1] == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = 1 + min(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1])

    return dp[len_a][len_b]
```

```python
def longest_word(s):
    words = s.split()
    return max(words, key=len, default="")
```

```python
def min_coins(coins, amount):
    dp = [float('inf')] * (amount + 1)
    dp[0] = 0
    for coin in coins:
        for x in range(coin, amount + 1):
            dp[x] = min(dp[x], dp[x - coin] + 1)
    return dp[amount] if dp[amount] != float('inf') else -1
```

```python
def lcs_length(a: str, b: str) -> int:
    m, n = len(a), len(b)
    if m == 0 or n == 0:
        return 0

    # Initialize a 2D array with (m+1) x (n+1) dimensions, all set to 0
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Fill dp array
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i - 1] == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    return dp[m][n]
```

```python
def longest_unique_substring(s: str) -> int:
    char_index = {}
    longest = 0
    start = 0

    for i, char in enumerate(s):
        if char in char_index and char_index[char] >= start:
            start = char_index[char] + 1
        char_index[char] = i
        longest = max(longest, i - start + 1)

    return longest
```

```python
def is_sorted(xs):
    return all(xs[i] <= xs[i+1] for i in range(len(xs) - 1))
```

```python
def longest_common_prefix(strs):
    if not strs:
        return ""

    shortest_str = min(strs, key=len)

    for i, char in enumerate(shortest_str):
        for other in strs:
            if other[i] != char:
                return shortest_str[:i]

    return shortest_str
```

```python
def is_valid_password(p):
    if len(p) < 8:
        return False
    upper_flag = False
    lower_flag = False
    digit_flag = False
    for char in p:
        if char.isupper():
            upper_flag = True
        elif char.islower():
            lower_flag = True
        elif char.isdigit():
            digit_flag = True
        if upper_flag and lower_flag and digit_flag:
            return True
    return False
```

```python
def max_subarray_sum(nums):
    if not nums:
        return 0
    max_sum = current_sum = nums[0]
    for num in nums[1:]:
        current_sum = max(num, current_sum + num)
        max_sum = max(max_sum, current_sum)
    return max_sum
```

```python
def to_base(n, b):
    if n == 0:
        return "0"
    digits = "0123456789ABCDEF"
    result = []
    negative = n < 0
    n = abs(n)

    while n:
        result.append(digits[n % b])
        n //= b

    if negative:
        result.append('-')

    return ''.join(reversed(result))
```

```python
def repeat_with_dash(s, n):
    if n <= 0:
        return ""
    else:
        return "-".join([s] * n)
```

```python
def two_sum(nums, target):
    num_indices = {}
    for index, num in enumerate(nums):
        complement = target - num
        if complement in num_indices:
            return [num_indices[complement], index]
        num_indices[num] = index
    return None
```

```python
def pascal_row(n):
    if n == 0:
        return [1]
    row = [1]
    for i in range(1, n + 1):
        row.append(row[i - 1] * (n - i + 1) // i)
    return row
```

```python
def matrix_multiply(a, b):
    m = len(a)  # Number of rows in matrix a
    n = len(b[0])  # Number of columns in matrix b
    result = [[0 for _ in range(n)] for _ in range(m)]
    for i in range(m):
        for j in range(n):
            for k in range(len(b)):
                result[i][j] += a[i][k] * b[k][j]
    return result
```
